import { PRESET_ID, PRESET_REGISTRY } from '@shinefold/config/constants';

import { formatPaletteDeclarations } from './theme-declarations';

export const SKIN_CSS_REPO_PATH = 'configs/tailwind/skins.css';

const DEFAULT_SKIN_HUE =
  PRESET_REGISTRY[PRESET_ID.CONSOLE].themeTokens.accentHue;

export const formatSkinCss = (): string => {
  const declarations = Object.entries(
    formatPaletteDeclarations(DEFAULT_SKIN_HUE),
  ).map(([property, value]) => `  ${property}: ${value};`);

  return [
    '/* Generated by `pnpm --filter @shinefold/config gen:skins`; never edit by hand. */',
    '',
    ':root {',
    ...declarations,
    '}',
    '',
  ].join('\n');
};
